1	// Fake DOM + controllable fetch for running public/app.js in node:vm.
2	// Every object handed to the script is a Proxy that records any member outside the
3	// spec's allowed list in `page.forbidden`, so tests can assert only allowed APIs were used.
4	import assert from 'node:assert/strict';
5	import { readFileSync } from 'node:fs';
6	import vm from 'node:vm';
7	
8	export const APP_PATH = new URL('../../public/app.js', import.meta.url);
9	const ELEMENT_MEMBERS = new Set(['textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren', 'addEventListener']);
10	const DOCUMENT_MEMBERS = new Set(['getElementById', 'createElement']);
11	const REPLY_MEMBERS = new Set(['status', 'json']);
12	const EVENT_MEMBERS = new Set(['preventDefault']);
13	const BROWSER_GLOBALS = ['window', 'self', 'console', 'setTimeout', 'setInterval', 'queueMicrotask', 'requestAnimationFrame',
14	  'XMLHttpRequest', 'location', 'navigator', 'alert', 'localStorage', 'sessionStorage', 'Headers', 'Request', 'Response',
15	  'URL', 'URLSearchParams', 'Event', 'CustomEvent', 'structuredClone', 'addEventListener'];
16	// The page's elements: id -> [tag, type].
17	const PAGE_ELEMENTS = {
18	  'booking-form': ['form'], room: ['select'], title: ['input', 'text'], date: ['input', 'date'],
19	  start: ['input', 'time'], end: ['input', 'time'], book: ['button', 'submit'], 'filter-date': ['input', 'date'],
20	  'show-all': ['button', 'button'], 'booking-list': ['ul'], error: ['p'],
21	};
22	
23	/** A text node made by `append(string)`. */
24	export class TextNode {
25	  constructor(data) { this.data = String(data); }
26	}
27	
28	/** Minimal element: children, textContent, value, type, disabled, listeners. */
29	export class FakeElement {
30	  constructor(page, tag, id) {
31	    this.page = page;
32	    this.tagName = tag;
33	    this.id = id;
34	    this.childNodes = [];
35	    this.listeners = {};
36	    this.attrs = { value: '', type: undefined, disabled: false };
37	  }
38	  get textContent() {
39	    return this.childNodes.map((n) => (n instanceof TextNode ? n.data : n.textContent)).join('');
40	  }
41	  set textContent(text) {
42	    this.page.log.push({ id: this.id, prop: 'textContent', value: String(text), bookDisabled: this.page.bookDisabled() });
43	    this.childNodes = String(text) === '' ? [] : [new TextNode(text)];
44	  }
45	  get value() { return this.tagName === 'select' ? this.selectValue() : this.attrs.value; }
46	  set value(v) {
47	    this.page.log.push({ id: this.id, prop: 'value', value: String(v), bookDisabled: this.page.bookDisabled() });
48	    if (this.tagName === 'select') this.selectedValue = String(v);
49	    else this.attrs = { ...this.attrs, value: String(v) };
50	  }
51	  get type() { return this.attrs.type; }
52	  set type(v) { this.attrs = { ...this.attrs, type: String(v) }; }
53	  get disabled() { return this.attrs.disabled; }
54	  set disabled(v) { this.attrs = { ...this.attrs, disabled: Boolean(v) }; }
55	  selectValue() {
56	    if (this.selectedValue !== undefined) return this.selectedValue;
57	    const first = this.childNodes.find((n) => n instanceof FakeElement && n.tagName === 'option');
58	    return first ? first.value : '';
59	  }
60	  append(...nodes) {
61	    this.childNodes = [...this.childNodes, ...nodes.map((n) => (typeof n === 'string' ? new TextNode(n) : unwrap(n)))];
62	  }
63	  replaceChildren(...nodes) {
64	    this.page.log.push({ id: this.id, prop: 'replaceChildren', value: nodes.length, bookDisabled: this.page.bookDisabled() });
65	    this.childNodes = nodes.map((n) => (typeof n === 'string' ? new TextNode(n) : unwrap(n)));
66	  }
67	  addEventListener(type, handler) {
68	    this.listeners = { ...this.listeners, [type]: [...(this.listeners[type] ?? []), handler] };
69	  }
70	  /** Test side: fires an event; returns { defaultPrevented }. */
71	  dispatch(type) {
72	    const state = { defaultPrevented: false };
73	    const event = guard(this.page, 'event', { preventDefault() { state.defaultPrevented = true; } }, EVENT_MEMBERS);
74	    (this.listeners[type] ?? []).forEach((handler) => handler.call(this.proxy, event));
75	    return state;
76	  }
77	}
78	
79	const RAW = Symbol('raw');
80	function unwrap(node) { return node?.[RAW] ?? node; }
81	
82	function guard(page, kind, target, allowed) {
83	  return new Proxy(target, {
84	    get(obj, key) {
85	      if (key === RAW) return obj;
86	      // `then` is probed by the engine when a reply resolves a promise; not a script access.
87	      const engineProbe = kind === 'reply' && key === 'then';
88	      if (typeof key === 'string' && !allowed.has(key) && !engineProbe) page.forbidden.push(`${kind}.${key}`);
89	      const value = Reflect.get(obj, key, obj);
90	      return typeof value === 'function' ? value.bind(obj) : value;
91	    },
92	    set(obj, key, value) {
93	      if (typeof key === 'string' && !allowed.has(key)) page.forbidden.push(`${kind}.${key}=`);
94	      return Reflect.set(obj, key, value, obj);
95	    },
96	  });
97	}
98	
99	function makeElement(page, tag, id) {
100	  const element = new FakeElement(page, tag, id);
101	  element.proxy = guard(page, `<${tag}>`, element, ELEMENT_MEMBERS);
102	  return element;
103	}
104	
105	/** One fetch call the test can settle: respond(), respondSlowJson(), respondUnparseable(), fail(). */
106	class FetchCall {
107	  constructor(page, url, options) {
108	    this.page = page;
109	    this.url = url;
110	    this.options = options;
111	    this.jsonCalls = 0;
112	    this.bookDisabledAtCall = page.bookDisabled();
113	    this.promise = new Promise((resolve, reject) => { this.resolve = resolve; this.reject = reject; });
114	  }
115	  reply(status, json) {
116	    const call = this;
117	    const target = { status, json() { call.jsonCalls += 1; return json(); } };
118	    this.resolve(guard(this.page, 'reply', target, REPLY_MEMBERS));
119	  }
120	  /** Settles with `status` and a body that json() parses (a fresh copy each time). */
121	  respond(status, body) {
122	    const text = JSON.stringify(body);
123	    this.reply(status, () => Promise.resolve(JSON.parse(text)));
124	  }
125	  /** Settles the status now; json() stays pending until the returned resolveJson(body) is called. */
126	  respondSlowJson(status) {
127	    let resolveJson;
128	    const pending = new Promise((resolve) => { resolveJson = resolve; });
129	    this.reply(status, () => pending);
130	    return (body) => resolveJson(JSON.parse(JSON.stringify(body)));
131	  }
132	  /** Settles with `status` and a body whose json() rejects (unparseable). */
133	  respondUnparseable(status) {
134	    this.reply(status, () => Promise.reject(new SyntaxError('Unexpected token')));
135	  }
136	  /** No reply at all: fetch rejects. */
137	  fail() { this.reject(new TypeError('Failed to fetch')); }
138	}
