140	/** Runs app.js against a fresh fake page. Returns the page handle used by tests. */
141	export function loadApp({ source = readFileSync(APP_PATH, 'utf8') } = {}) {
142	  const page = { forbidden: [], log: [], calls: [], elements: {} };
143	  page.bookDisabled = () => page.elements.book?.attrs.disabled ?? false;
144	  Object.entries(PAGE_ELEMENTS).forEach(([id, [tag, type]]) => {
145	    const element = makeElement(page, tag, id);
146	    element.attrs = { ...element.attrs, type };
147	    page.elements[id] = element;
148	  });
149	  page.created = [];
150	  const document = guard(page, 'document', {
151	    getElementById: (id) => page.elements[id]?.proxy ?? null,
152	    createElement: (tag) => {
153	      const element = makeElement(page, String(tag).toLowerCase(), undefined);
154	      page.created.push(element);
155	      return element.proxy;
156	    },
157	  }, DOCUMENT_MEMBERS);
158	  const fetch = (url, options) => {
159	    const call = new FetchCall(page, url, options);
160	    page.calls.push(call);
161	    return call.promise;
162	  };
163	  const sandbox = { document, fetch };
164	  BROWSER_GLOBALS.forEach((name) => {
165	    Object.defineProperty(sandbox, name, { get() { page.forbidden.push(`global.${name}`); return undefined; } });
166	  });
167	  vm.createContext(sandbox);
168	  vm.runInContext(source, sandbox, { filename: 'app.js' });
169	  return page;
170	}
