172	/** Lets pending promise chains in the script run to completion. */
173	export async function flush(rounds = 10) {
174	  for (let i = 0; i < rounds; i += 1) await new Promise((resolve) => setImmediate(resolve));
175	}
176	
177	/** Describes an element's children for exact assertions: strings for text nodes, elements as-is. */
178	export function childSummary(element) {
179	  return element.childNodes.map((n) => (n instanceof TextNode ? { text: n.data } : { tag: n.tagName, type: n.type, text: n.textContent }));
180	}
181	
182	/** Booking fixture. */
183	export function booking(overrides = {}) {
184	  return { id: 1, room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides };
185	}
186	
187	/**
188	 * Loads the app and settles the two startup fetches: rooms with the three rooms,
189	 * the list with `bookings`. Returns the page with no pending calls.
190	 */
191	export async function loadReadyApp(bookings = []) {
192	  const page = loadApp();
193	  await flush();
194	  page.calls.find((c) => c.url === '/api/rooms').respond(200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
195	  page.calls.find((c) => c.url === '/api/bookings').respond(200, { bookings });
196	  await flush();
197	  return page;
198	}
199	
200	/** Asserts the script touched no browser API outside the spec's allowed list. */
201	export function assertOnlyAllowedApis(page) {
202	  assert.deepEqual(page.forbidden, []);
203	}
204	
205	/** The Cancel button elements currently in the list, in order. */
206	export function cancelButtons(page) {
207	  return page.elements['booking-list'].childNodes.flatMap((li) => li.childNodes.filter((n) => n instanceof FakeElement && n.tagName === 'button'));
208	}
