1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { loadApp, flush, childSummary, booking, loadReadyApp } from './helpers/fake-dom.mjs';
4	
5	const ROOMS = ['Aurora', 'Borealis', 'Cosmos'];
6	
7	function assertOnlyAllowedApis(page) {
8	  assert.deepEqual(page.forbidden, []);
9	}
10	function isGet(call) {
11	  return call.options === undefined || call.options.method === 'GET';
12	}
13	function callFor(page, url) {
14	  return page.calls.find((c) => c.url === url);
15	}
16	function lis(page) {
17	  return page.elements['booking-list'].childNodes;
18	}
19	function summaries(page) {
20	  return lis(page).map((li) => childSummary(li));
21	}
22	function errorText(page) {
23	  return page.elements.error.textContent;
24	}
25	async function changeFilter(page, value) {
26	  page.elements['filter-date'].value = value;
27	  const before = page.calls.length;
28	  page.elements['filter-date'].dispatch('change');
29	  await flush();
30	  assert.equal(page.calls.length, before + 1);
31	  return page.calls[before];
32	}
33	async function roomsReply(reply) {
34	  const page = loadApp();
35	  await flush();
36	  reply(callFor(page, '/api/rooms'));
37	  await flush();
38	  return page;
39	}
40	const row = (text) => [{ text }, { tag: 'button', type: 'button', text: 'Cancel' }];
41	
42	test('startup issues both GET fetches synchronously without waiting for rooms', () => {
43	  const page = loadApp();
44	  assert.equal(page.calls.length, 2);
45	  assert.deepEqual(page.calls.map((c) => c.url).sort(), ['/api/bookings', '/api/rooms']);
46	  for (const call of page.calls) {
47	    assert.ok(isGet(call));
48	    assert.equal(call.options?.body, undefined);
49	  }
50	  assertOnlyAllowedApis(page);
51	});
