53	test('rooms success fills #room with one option per room in order, value equals name', async () => {
54	  const page = await roomsReply((c) => c.respond(200, { rooms: ROOMS }));
55	  assert.deepEqual(childSummary(page.elements.room), ROOMS.map((text) => ({ tag: 'option', type: undefined, text })));
56	  assert.deepEqual(page.elements.room.childNodes.map((o) => o.value), ROOMS);
57	  assertOnlyAllowedApis(page);
58	});
