60	for (const [status, body, expected] of [
61	  [500, { error: 'boom' }, 'boom'],
62	  [404, { error: 5 }, 'Request failed.'],
63	  [500, ['x'], 'Request failed.'],
64	  [500, null, 'Request failed.'],
65	]) {
66	  test(`rooms error status ${status} with body ${JSON.stringify(body)} shows "${expected}" and leaves #room empty`, async () => {
67	    const page = await roomsReply((c) => c.respond(status, body));
68	    assert.equal(errorText(page), expected);
69	    assert.deepEqual(page.elements.room.childNodes, []);
70	    assertOnlyAllowedApis(page);
71	  });
72	}
73	
74	for (const [name, act] of [
75	  ['fetch fails', (c) => c.fail()],
76	  ['500 unparseable', (c) => c.respondUnparseable(500)],
77	  ['200 unparseable', (c) => c.respondUnparseable(200)],
78	]) {
79	  test(`rooms with no usable reply (${name}) shows unreachable message and leaves #room empty`, async () => {
80	    const page = await roomsReply(act);
81	    assert.equal(errorText(page), 'Could not reach the server.');
82	    assert.deepEqual(page.elements.room.childNodes, []);
83	    assertOnlyAllowedApis(page);
84	  });
85	}
