87	test('list renders each booking as li with one text node and a Cancel button, in reply order', async () => {
88	  const a = booking({ id: 2, room: 'Borealis', title: 'Later', date: '2026-11-05', start: '13:00', end: '14:30' });
89	  const b = booking({ id: 1 });
90	  const page = await loadReadyApp([a, b]);
91	  assert.equal(lis(page).length, 2);
92	  assert.deepEqual(summaries(page), [
93	    row('2026-11-05 13:00-14:30 Borealis: Later'),
94	    row('2026-11-03 09:00-10:00 Aurora: Standup'),
95	  ]);
96	  assert.equal(lis(page)[0].childNodes[0].constructor.name, 'TextNode');
97	  assertOnlyAllowedApis(page);
98	});
