100	test('list shows a title with markup literally as text', async () => {
101	  const page = await loadReadyApp([booking({ title: '<b>x</b>' })]);
102	  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: <b>x</b>')]);
103	  assertOnlyAllowedApis(page);
