106	test('list text has no extra whitespace beyond the title', async () => {
107	  const page = await loadReadyApp([booking({ title: 'Plan  ' })]);
108	  assert.equal(lis(page)[0].childNodes[0].data, '2026-11-03 09:00-10:00 Aurora: Plan  ');
109	  assertOnlyAllowedApis(page);
