112	test('empty list shows exactly one li containing only the text node "No bookings."', async () => {
113	  const page = await loadReadyApp([]);
114	  assert.equal(lis(page).length, 1);
115	  assert.deepEqual(childSummary(lis(page)[0]), [{ text: 'No bookings.' }]);
