119	test('a refetch replaces the rendered list instead of appending', async () => {
120	  const page = await loadReadyApp([booking({ id: 1 }), booking({ id: 2 }), booking({ id: 3 })]);
121	  assert.equal(lis(page).length, 3);
122	  const call = await changeFilter(page, '2026-11-03');
123	  call.respond(200, { bookings: [booking({ id: 4, title: 'Only' })] });
124	  await flush();
125	  assert.equal(lis(page).length, 1);
126	  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: Only')]);
127	  assertOnlyAllowedApis(page);
128	});
