130	for (const [name, act, expected] of [
131	  ['error status', (c) => c.respond(400, { error: 'date must be a valid YYYY-MM-DD date' }), 'date must be a valid YYYY-MM-DD date'],
132	  ['no reply', (c) => c.fail(), 'Could not reach the server.'],
133	  ['unparseable', (c) => c.respondUnparseable(200), 'Could not reach the server.'],
134	]) {
135	  test(`list fetch failure (${name}) shows the error and leaves the list unchanged`, async () => {
136	    const page = await loadReadyApp([booking()]);
137	    const before = [...lis(page)];
138	    const beforeSummary = summaries(page);
139	    const call = await changeFilter(page, 'bad');
140	    act(call);
141	    await flush();
142	    assert.equal(errorText(page), expected);
143	    assert.equal(lis(page).length, before.length);
144	    assert.ok(lis(page).every((li, i) => li === before[i]));
145	    assert.deepEqual(summaries(page), beforeSummary);
146	    assertOnlyAllowedApis(page);
147	  });
148	}
