150	test('list success leaves an existing #error message alone', async () => {
151	  const page = loadApp();
152	  await flush();
153	  callFor(page, '/api/rooms').respond(500, { error: 'boom' });
154	  callFor(page, '/api/bookings').respond(200, { bookings: [booking()] });
155	  await flush();
156	  assert.equal(errorText(page), 'boom');
157	  assert.equal(lis(page).length, 1);
158	  assertOnlyAllowedApis(page);
159	});
