161	test('stale list fetch (a): older success arriving after newer success is ignored', async () => {
162	  const page = loadApp();
163	  const a = callFor(page, '/api/bookings');
164	  const b = await changeFilter(page, '2026-11-03');
165	  b.respond(200, { bookings: [booking({ title: 'b1' })] });
166	  await flush();
167	  a.respond(200, { bookings: [booking({ title: 'a1' })] });
168	  await flush();
169	  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: b1')]);
170	  assertOnlyAllowedApis(page);
171	});
172	
173	test('stale list fetch (b): older success arriving while newer is pending changes nothing', async () => {
174	  const page = loadApp();
175	  const a = callFor(page, '/api/bookings');
176	  const b = await changeFilter(page, '2026-11-03');
177	  a.respond(200, { bookings: [booking({ title: 'a1' })] });
178	  await flush();
179	  assert.deepEqual(lis(page), []);
180	  b.respond(200, { bookings: [booking({ title: 'b1' })] });
181	  await flush();
182	  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: b1')]);
183	  assertOnlyAllowedApis(page);
184	});
