186	test('stale list fetch (c): older error status after newer success leaves #error and list alone', async () => {
187	  const page = loadApp();
188	  const a = callFor(page, '/api/bookings');
189	  const b = await changeFilter(page, '2026-11-03');
190	  b.respond(200, { bookings: [booking({ title: 'b1' })] });
191	  await flush();
192	  a.respond(500, { error: 'old' });
193	  await flush();
194	  assert.equal(errorText(page), '');
195	  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: b1')]);
196	  assertOnlyAllowedApis(page);
197	});
