199	test('stale list fetch (d): older network failure after newer success leaves #error alone', async () => {
200	  const page = loadApp();
201	  const a = callFor(page, '/api/bookings');
202	  const b = await changeFilter(page, '2026-11-03');
203	  b.respond(200, { bookings: [booking({ title: 'b1' })] });
204	  await flush();
205	  a.fail();
206	  await flush();
207	  assert.equal(errorText(page), '');
208	  assert.equal(lis(page).length, 1);
209	  assertOnlyAllowedApis(page);
