1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { flush, booking, loadReadyApp, cancelButtons } from './helpers/fake-dom.mjs';
4	
5	function assertOnlyAllowedApis(page) {
6	  assert.deepEqual(page.forbidden, []);
7	}
8	const el = (page, id) => page.elements[id];
9	const errorText = (page) => el(page, 'error').textContent;
10	const bookDisabled = (page) => el(page, 'book').disabled;
11	
12	function fillForm(page, overrides = {}) {
13	  const values = { room: 'Borealis', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides };
14	  for (const [id, value] of Object.entries(values)) el(page, id).value = value;
15	}
